{"file_path":"/home/user/bench-runs/e13-probe-review-sonnet-t5t6-20260927T231225Z/cell-nq87a6/src/diff.js","content":"/**
 * Computes the changes needed to turn `base` into `side` using a longest
 * common subsequence over whole lines, with the tie-break rule described in
 * the task: when multiple LCSs are equally long, prefer the one whose
 * matches occur earliest, walking both documents from the start and
 * advancing whichever side leaves the larger remaining LCS, preferring to
 * advance the base when the two options tie.
 *
 * Returns a list of changes `{ baseStart, baseEnd, sideLines }` describing a
 * run of base lines (from baseStart to baseEnd, exclusive) replaced by
 * sideLines. The changes are ordered by baseStart.
 */
export function computeChanges(side, base) {
  const n = side.length
  const m = base.length

  // dp[i][j] = length of the LCS of side[i:] and base[j:]
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) dp[i] = new Int32Array(m + 1)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      if (side[i] === base[j]) {
        dp[i][j] = dp[i + 1][j + 1] + 1
      } else {
        dp[i][j] = Math.max(dp[i + 1][j], dp[i][j + 1])
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (side[i] === base[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (dp[i + 1][j] > dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }

  const changes = []
  let prevI = -1
  let prevJ = -1
  for (const [mi, mj] of [...matches, [n, m]]) {
    const baseStart = prevJ + 1
    const baseEnd = mj
    const sideLines = side.slice(prevI + 1, mi)
    if (baseEnd > baseStart || sideLines.length > 0) {
      changes.push({ baseStart, baseEnd, sideLines })
    }
    prevI = mi
    prevJ = mj
  }
  return changes
}
"}

